package com.lims.dao;

import com.lims.model.*;import com.lims.util.DBContext;import java.sql.*;import java.util.*;import java.util.logging.Level;import java.util.logging.Logger;
public class ManagerCatalogDAO{
 private static final Logger LOG=Logger.getLogger(ManagerCatalogDAO.class.getName());
 public List<Brand> brands(){List<Brand>a=new ArrayList<>();try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("SELECT BrandID,BrandName,Status FROM BRANDS ORDER BY BrandName");ResultSet r=p.executeQuery()){while(r.next()){Brand x=new Brand();x.setBrandId(r.getInt(1));x.setBrandName(r.getString(2));x.setStatus(r.getString(3));a.add(x);}}catch(SQLException e){LOG.log(Level.SEVERE,"brands",e);}return a;}
 public List<ProductLine> lines(){List<ProductLine>a=new ArrayList<>();try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("SELECT l.ProductLineID,l.BrandID,b.BrandName,l.LineName,l.Status FROM PRODUCT_LINES l JOIN BRANDS b ON b.BrandID=l.BrandID ORDER BY b.BrandName,l.LineName");ResultSet r=p.executeQuery()){while(r.next()){ProductLine x=new ProductLine();x.setProductLineId(r.getInt(1));x.setBrandId(r.getInt(2));x.setBrandName(r.getString(3));x.setLineName(r.getString(4));x.setStatus(r.getString(5));a.add(x);}}catch(SQLException e){LOG.log(Level.SEVERE,"product lines",e);}return a;}
 public List<Product> products(){List<Product>a=new ArrayList<>();String q="SELECT p.*,l.LineName,b.BrandName FROM PRODUCTS p JOIN PRODUCT_LINES l ON l.ProductLineID=p.ProductLineID JOIN BRANDS b ON b.BrandID=l.BrandID ORDER BY b.BrandName,l.LineName,p.ProductName";try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())a.add(readProduct(r));}catch(SQLException e){LOG.log(Level.SEVERE,"products",e);}return a;}
 public Product product(int id){try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("SELECT p.*,l.LineName,b.BrandName FROM PRODUCTS p JOIN PRODUCT_LINES l ON l.ProductLineID=p.ProductLineID JOIN BRANDS b ON b.BrandID=l.BrandID WHERE p.ProductID=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?readProduct(r):null;}}catch(SQLException e){return null;}}
 public List<Customer> customers(){List<Customer>a=new ArrayList<>();try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("SELECT CustomerID,CustomerName,Phone,Email,Address,Status FROM CUSTOMERS ORDER BY CustomerName");ResultSet r=p.executeQuery()){while(r.next())a.add(readCustomer(r));}catch(SQLException e){LOG.log(Level.SEVERE,"customers",e);}return a;}
 public Customer customer(int id){try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("SELECT CustomerID,CustomerName,Phone,Email,Address,Status FROM CUSTOMERS WHERE CustomerID=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?readCustomer(r):null;}}catch(SQLException e){return null;}}
 public boolean saveBrand(Brand x){String q=x.getBrandId()>0?"UPDATE BRANDS SET BrandName=?,Status=? WHERE BrandID=?":"INSERT INTO BRANDS(BrandName,Status) VALUES(?,?)";try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,x.getBrandName());p.setString(2,x.getStatus());if(x.getBrandId()>0)p.setInt(3,x.getBrandId());return p.executeUpdate()==1;}catch(SQLException e){LOG.log(Level.WARNING,"save brand",e);return false;}}
 public boolean deleteBrand(int id){try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM BRANDS WHERE BrandID=? AND NOT EXISTS(SELECT 1 FROM PRODUCT_LINES WHERE BrandID=?)")){p.setInt(1,id);p.setInt(2,id);return p.executeUpdate()==1;}catch(SQLException e){return false;}}
 public boolean saveLine(ProductLine x){String q=x.getProductLineId()>0?"UPDATE PRODUCT_LINES SET BrandID=?,LineName=?,Status=? WHERE ProductLineID=?":"INSERT INTO PRODUCT_LINES(BrandID,LineName,Status) VALUES(?,?,?)";try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,x.getBrandId());p.setString(2,x.getLineName());p.setString(3,x.getStatus());if(x.getProductLineId()>0)p.setInt(4,x.getProductLineId());return p.executeUpdate()==1;}catch(SQLException e){LOG.log(Level.WARNING,"save product line",e);return false;}}
 public boolean deleteLine(int id){try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM PRODUCT_LINES WHERE ProductLineID=? AND NOT EXISTS(SELECT 1 FROM PRODUCTS WHERE ProductLineID=?)")){p.setInt(1,id);p.setInt(2,id);return p.executeUpdate()==1;}catch(SQLException e){return false;}}
 public boolean setLineStatus(int id,String status){try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("UPDATE PRODUCT_LINES SET Status=? WHERE ProductLineID=?")){p.setString(1,status);p.setInt(2,id);return p.executeUpdate()==1;}catch(SQLException e){return false;}}
 public boolean saveProduct(Product x){boolean create=x.getProductId()<=0;String q=create?"INSERT INTO PRODUCTS(ProductCode,ProductName,ProductLineID,CPU,RAM,Storage,GPU,Screen,UnitPrice,Status) VALUES(?,?,?,?,?,?,?,?,?,?)":"UPDATE PRODUCTS SET ProductCode=?,ProductName=?,ProductLineID=?,CPU=?,RAM=?,Storage=?,GPU=?,Screen=?,UnitPrice=?,Status=? WHERE ProductID=?";try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q,create?Statement.RETURN_GENERATED_KEYS:Statement.NO_GENERATED_KEYS)){bindProduct(p,x);if(!create)p.setInt(11,x.getProductId());if(p.executeUpdate()!=1)return false;if(create)try(ResultSet keys=p.getGeneratedKeys()){if(keys.next())x.setProductId(keys.getInt(1));}return true;}catch(SQLException e){LOG.log(Level.WARNING,"save product",e);return false;}}
 public boolean deactivateProduct(int id){try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("UPDATE PRODUCTS SET Status='INACTIVE' WHERE ProductID=? AND Status<>'INACTIVE'")){p.setInt(1,id);return p.executeUpdate()==1;}catch(SQLException e){return false;}}
 public boolean saveCustomer(Customer x){boolean create=x.getCustomerId()<=0;String q=create?"INSERT INTO CUSTOMERS(CustomerName,Phone,Email,Address,Status) VALUES(?,?,?,?,?)":"UPDATE CUSTOMERS SET CustomerName=?,Phone=?,Email=?,Address=?,Status=? WHERE CustomerID=?";try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q,create?Statement.RETURN_GENERATED_KEYS:Statement.NO_GENERATED_KEYS)){p.setString(1,x.getCustomerName());p.setString(2,x.getPhone());p.setString(3,blankNull(x.getEmail()));p.setString(4,blankNull(x.getAddress()));p.setString(5,x.getStatus());if(!create)p.setInt(6,x.getCustomerId());if(p.executeUpdate()!=1)return false;if(create)try(ResultSet keys=p.getGeneratedKeys()){if(keys.next())x.setCustomerId(keys.getInt(1));}return true;}catch(SQLException e){LOG.log(Level.WARNING,"save customer",e);return false;}}
 public boolean deactivateCustomer(int id){try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement("UPDATE CUSTOMERS SET Status='INACTIVE' WHERE CustomerID=?")){p.setInt(1,id);return p.executeUpdate()==1;}catch(SQLException e){return false;}}
 private void bindProduct(PreparedStatement p,Product x)throws SQLException{p.setString(1,x.getProductCode());p.setString(2,x.getProductName());p.setInt(3,x.getProductLineId());p.setString(4,x.getCpu());p.setString(5,x.getRam());p.setString(6,x.getStorage());p.setString(7,blankNull(x.getGpu()));p.setString(8,blankNull(x.getScreen()));p.setBigDecimal(9,x.getUnitPrice());p.setString(10,x.getStatus());}
 private Product readProduct(ResultSet r)throws SQLException{Product x=new Product();x.setProductId(r.getInt("ProductID"));x.setProductCode(r.getString("ProductCode"));x.setProductName(r.getString("ProductName"));x.setProductLineId(r.getInt("ProductLineID"));x.setLineName(r.getString("LineName"));x.setBrandName(r.getString("BrandName"));x.setCpu(r.getString("CPU"));x.setRam(r.getString("RAM"));x.setStorage(r.getString("Storage"));x.setGpu(r.getString("GPU"));x.setScreen(r.getString("Screen"));x.setUnitPrice(r.getBigDecimal("UnitPrice"));x.setStatus(r.getString("Status"));return x;}
 private Customer readCustomer(ResultSet r)throws SQLException{Customer x=new Customer();x.setCustomerId(r.getInt("CustomerID"));x.setCustomerName(r.getString("CustomerName"));x.setPhone(r.getString("Phone"));x.setEmail(r.getString("Email"));x.setAddress(r.getString("Address"));x.setStatus(r.getString("Status"));return x;}
 private String blankNull(String s){return s==null||s.isBlank()?null:s.trim();}
}
